package com.example.parcel.application.parcel;

import static org.junit.jupiter.api.Assertions.*;

import com.example.parcel.domain.parcel.*;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;
import org.junit.jupiter.api.Test;

class RegisterParcelTest {

    static final class FakeRepository implements ParcelRepository {
        final Map<ParcelId, Parcel> store = new HashMap<>();

        public void save(Parcel parcel) { store.put(parcel.id(), parcel); }

        public Optional<Parcel> findById(ParcelId id) { return Optional.ofNullable(store.get(id)); }
    }

    private final FakeRepository repository = new FakeRepository();
    private final RegisterParcel registerParcel = new RegisterParcel(repository);

    @Test
    void storesRegisteredParcel() {
        registerParcel.execute(new ParcelId("P-1"), 12.5);
        assertTrue(repository.findById(new ParcelId("P-1")).isPresent());
    }

    @Test
    void storesNothingWhenTooHeavy() {
        assertThrows(ParcelTooHeavyException.class, () -> registerParcel.execute(new ParcelId("P-2"), 31));
        assertTrue(repository.store.isEmpty());
    }
}
