package com.example.parcel.app.parcel;

import com.example.parcel.domain.parcel.ParcelTooHeavyException;
import jakarta.ws.rs.core.Response;
import org.jboss.resteasy.reactive.server.ServerExceptionMapper;

public class ParcelExceptionMappers {

    @ServerExceptionMapper
    Response tooHeavy(ParcelTooHeavyException e) {
        return Response.status(422).entity(e.getMessage()).build();
    }

    @ServerExceptionMapper
    Response invalid(IllegalArgumentException e) {
        return Response.status(400).entity(e.getMessage()).build();
    }
}
