package com.example.parcel.domain.parcel;

import static org.junit.jupiter.api.Assertions.*;

import org.junit.jupiter.api.Test;

class ParcelTest {

    private final ParcelId id = new ParcelId("P-1");

    @Test
    void registersParcelUpToThirtyKg() {
        Parcel parcel = Parcel.register(id, 30);
        assertEquals(id, parcel.id());
        assertEquals(30, parcel.weightKg());
    }

    @Test
    void refusesParcelHeavierThanThirtyKg() {
        assertThrows(ParcelTooHeavyException.class, () -> Parcel.register(id, 30.01));
    }

    @Test
    void refusesNonPositiveWeight() {
        assertThrows(IllegalArgumentException.class, () -> Parcel.register(id, 0));
    }

    @Test
    void refusesBlankId() {
        assertThrows(IllegalArgumentException.class, () -> new ParcelId(" "));
    }
}
